from decimal import Decimal

_CENT = Decimal("0.01")

def split_installments(total: str, n: int) -> list[Decimal]:
    # Validate n.
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be an integer >= 1")
    if n < 1:
        raise ValueError("n must be an integer >= 1")
    # Validate total.
    if not isinstance(total, str):
        raise ValueError("invalid total")
    try:
        d = Decimal(total)
    except Exception:
        raise ValueError("invalid total") from None
    if not d.is_finite():
        raise ValueError("invalid total")
    if d < 0:
        raise ValueError("invalid total")
    exp = d.as_tuple().exponent
    if not isinstance(exp, int):
        raise ValueError("invalid total")
    if exp < -2:
        raise ValueError("invalid total")
    # Total cents as exact integer without using context-limited
    # Decimal arithmetic (works for arbitrarily many digits).
    tup = d.as_tuple()
    digits = tup.digits
    if digits:
        int_digits = int("".join(map(str, digits)))
    else:
        int_digits = 0
    # exp >= -2 here, so exp + 2 >= 0.
    total_cents = int_digits * (10 ** (tup.exponent + 2))
    base = total_cents // n
    rem = total_cents % n
    out: list[Decimal] = []
    for i in range(n):
        c = base + 1 if i < rem else base
        q, r = divmod(c, 100)
        out.append(Decimal(f"{q}.{r:02d}"))
    return out
